MAX_REQUEST = 65536
MAX_REPLY = 1048576
MAX_CONTINUITY = 32768
IDENTIFIER = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}\Z")
SKILLS = {"transport", "recover_held", "setup", "cycle", "inspect", "observe", "wait", "cancel"}
